const partsUrl=@json(route('public.spare-parts.lookup'));
let customer=null, asset=null, selectedPart=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function syncSummary(){ $('#sumCustomer').textContent=$('#company_name').value||'—'; $('#sumAsset').textContent=asset?.asset_code||$('#manualAssetType').value||'—'; $('#sumPart').textContent=selectedPart?.name||$('#manualPartName').value||'—'; const u=$('#urgency').value; $('#sumPriority').textContent=ar?({NORMAL:'متوسطة',PRIORITY:'مهم',URGENT:'عاجل'}[u]||u):u; }
$$('input[name="customer_mode"]').forEach(r=>r.addEventListener('change',()=>{$('#existingCustomer').classList.toggle('hidden',r.checked&&r.value==='new'); if(r.checked&&r.value==='new'){customer=null; ['company_name','responsible_person','mobile','email'].forEach(id=>$('#'+id).value='');syncSummary();}}));
$$('input[name="asset_mode"]').forEach(r=>r.addEventListener('change',()=>{if(!r.checked)return; const reg=r.value==='registered';$('#registeredAsset').classList.toggle('hidden',!reg);$('#unregisteredAsset').classList.toggle('hidden',reg); if(!reg){asset=null;$('#asset_id').value='';}}));
$('#customerLookup').addEventListener('click',async()=>{const key=$('#customerKey').value.trim();if(!key)return;const box=$('#customerResult');box.classList.add('show');box.textContent=ar?'جارٍ البحث...':'Searching...';try{const res=await fetch(customerUrl+'?customer_number='+encodeURIComponent(key),{headers:{Accept:'application/json'}});const data=await res.json();if(!res.ok)throw new Error(data.message||'Not found');customer=data.customer;$('#company_name').value=customer.name||'';$('#responsible_person').value=customer.contact_name||'';$('#mobile').value=customer.phone||'';$('#email').value=customer.email||'';$('#site_city').value=customer.city||'';$('#site_address').value=customer.address||'';box.innerHTML='<strong>✓ '+esc(customer.name)+'</strong><span>'+esc(customer.customer_code||'')+' · '+esc(customer.phone||'')+'</span>';syncSummary();}catch(e){box.innerHTML='<strong>'+esc(e.message)+'</strong>';}});
$('#assetLookup').addEventListener('click',async()=>{const key=$('#assetKey').value.trim();if(!key)return;const box=$('#assetResult');box.classList.add('show');box.textContent=ar?'جارٍ البحث...':'Searching...';try{let url;if(customer){url=assetsUrl+'?customer_id='+encodeURIComponent(customer.id)+'&key='+encodeURIComponent(key);}else{url=@json(route('public.asset.lookup'))+'?key='+encodeURIComponent(key);}const res=await fetch(url,{headers:{Accept:'application/json'}});const data=await res.json();if(!res.ok)throw new Error(data.message||'Not found');asset=data.asset||(data.assets&&data.assets[0]);if(!asset)throw new Error(ar?'لم يتم العثور على الأصل.':'Asset not found.');$('#asset_id').value=asset.id;$('#asset_type').value=asset.asset_category||asset.asset_type||asset.type||asset.name||'SPARE_PARTS';$('#equipment_brand').value=asset.manufacturer||asset.brand||'';$('#equipment_model').value=asset.model_no||asset.model||'';$('#site_name').value=asset.site_name||'Main Site';$('#site_city').value=asset.site_city||$('#site_city').value;$('#site_address').value=asset.site_address||$('#site_address').value;$('#latitude').value=asset.latitude||'';$('#longitude').value=asset.longitude||'';if(asset.customer_name&&!$('#company_name').value)$('#company_name').value=asset.customer_name;box.innerHTML='<strong>✓ '+esc(asset.name||asset.asset_code)+'</strong><span>'+esc(asset.asset_code||'')+' · '+esc(asset.manufacturer||asset.brand||'')+' '+esc(asset.model_no||asset.model||'')+'</span>';syncSummary();}catch(e){box.innerHTML='<strong>'+esc(e.message)+'</strong>';}});
async function loadParts(linked=false){const body=$('#partsBody');body.innerHTML='<tr><td colspan="7" class="part-note">'+(ar?'جارٍ تحميل قطع الغيار...':'Loading parts...')+'</td></tr>';const q=$('#partQuery').value.trim();let url=partsUrl+'?q='+encodeURIComponent(q);if(linked&&asset?.id)url+='&asset_id='+asset.id;try{const res=await fetch(url,{headers:{Accept:'application/json'}});const data=await res.json();if(!res.ok)throw new Error('Lookup failed');const items=data.items||[];if(!items.length){body.innerHTML='<tr><td colspan="7" class="part-note">'+(ar?'لا توجد نتائج مطابقة.':'No matching results.')+'</td></tr>';return;}body.innerHTML=items.map((p,i)=>{const st=p.availability==='AVAILABLE'?['ok',ar?'متوفر':'Available']:p.availability==='LIMITED'?['low',ar?'كمية محدودة':'Limited']:['no',ar?'غير متوفر':'Not Available'];return '<tr><td><strong>'+esc(p.name)+'</strong><small>'+esc(p.uom||'')+'</small></td><td>'+esc(p.item_code)+'</td><td>'+(p.compatible===true?'✓ '+(ar?'مرتبط بالأصل':'Linked'):p.compatible===false?(ar?'غير مؤكد':'Not confirmed'):'—')+'</td><td><span class="status '+st[0]+'">'+st[1]+'</span></td><td>'+esc(p.preferred_warehouse_code|| (ar?'المستودع الرئيسي':'Main Warehouse'))+'</td><td><input id="qty'+i+'" type="number" min="1" value="1" style="width:65px;min-height:34px"></td><td><button type="button" class="add" data-index="'+i+'">'+(p.availability==='NOT_AVAILABLE'?(ar?'طلب عرض سعر':'Request Quote'):(ar?'إضافة':'Add'))+'</button></td></tr>'}).join('');$$('.add').forEach(b=>b.addEventListener('click',()=>{const p=items[+b.dataset.index];p.qty=Math.max(1,parseInt($('#qty'+b.dataset.index).value||'1',10));selectPart(p);}));}catch(e){body.innerHTML='<tr><td colspan="7" class="part-note">'+esc(e.message)+'</td></tr>';}}
function selectPart(p){selectedPart=p;$('#selectedPart').classList.add('show');$('#selectedPart').innerHTML='✓ <strong>'+esc(p.name)+'</strong> · '+esc(p.item_code||'')+' · '+(ar?'الكمية ':'Qty ')+esc(p.qty||1);syncSummary();}
$('#partSearch').addEventListener('click',()=>loadParts(false));
$$('.tab').forEach(t=>t.addEventListener('click',()=>{$$('.tab').forEach(x=>x.classList.remove('active'));t.classList.add('active');const mode=t.dataset.tab;$('#inventoryPanel').classList.toggle('hidden',mode==='unknown');$('#unknownPanel').classList.toggle('hidden',mode!=='unknown');if(mode==='linked')loadParts(true);if(mode==='inventory')loadParts(false);}));
['company_name','manualAssetType','manualPartName'].forEach(id=>$('#'+id).addEventListener('input',syncSummary));$('#urgency').addEventListener('change',syncSummary);
$('#saveDraft').addEventListener('click',()=>{const draft={company:$('#company_name').value,person:$('#responsible_person').value,mobile:$('#mobile').value,email:$('#email').value,city:$('#site_city').value,notes:$('#notes').value};localStorage.setItem('unifco_spare_parts_draft',JSON.stringify(draft));alert(ar?'تم حفظ المسودة على هذا الجهاز.':'Draft saved on this device.');});
$('#spareForm').addEventListener('submit',e=>{const manualMode=$('input[name="asset_mode"]:checked').value==='unregistered';if(manualMode){$('#asset_type').value=$('#manualAssetType').value||'SPARE_PARTS';$('#equipment_brand').value=$('#manualBrand').value;$('#equipment_model').value=$('#manualModel').value;}const unknown=!$('#unknownPanel').classList.contains('hidden');if(unknown&&!selectedPart){selectedPart={name:$('#manualPartName').value|| (ar?'قطعة غير محددة':'Unidentified Part'),item_code:$('#manualPartNo').value,qty:$('#manualQty').value||1};}if(!selectedPart){e.preventDefault();alert(ar?'اختر قطعة من المستودع أو اختر «لا أعرف القطعة» وأدخل البيانات المتاحة.':'Select a part or use “I do not know the part”.');return;}const parts='Part: '+(selectedPart.name||'')+' | Part No: '+(selectedPart.item_code||'')+' | Qty: '+(selectedPart.qty||1);const assetInfo=manualMode?'Asset: '+($('#manualAssetType').value||'')+' | Serial: '+($('#manualSerial').value||''):'Asset: '+(asset?.asset_code||'');$('#details').value=[parts,assetInfo,$('#notes').value].filter(Boolean).join('\n');if(!$('#site_city').value){e.preventDefault();alert(ar?'أدخل المدينة لإكمال الطلب.':'Enter the city.');return;} });
syncSummary();
})();
</script>
</body>
</html>